xql_query:
// ============================================================
// Rule: BYT_User Removed from Admin Group
// Vendor: BeyondTrust
// Objective:
// Detect activity associated with BYT_User Removed from Admin Group.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1531 - Account Access Removal

// Fonte de dados: logs do BeyondTrust Password Safe
dataset = beyondtrust_passwordsafe_raw  

// Filtra apenas eventos que contenham o termo "weslley.teste" no log bruto
// e que sejam da categoria "Configure" com evento do tipo "Delete"
| filter _raw_log contains "Administrators"  
       and category = "Configure"   
       and event_name = "Delete"  

// Seleciona os campos relevantes para análise
| fields user,           // Usuário que executou a ação
         category,       // Categoria do evento (ex.: Configure)
         user_name,      // Nome do usuário associado
         event_name,     // Tipo de evento (ex.: Delete)
         group_name,     // Nome do grupo afetado
         _raw_log        // Log bruto para contexto completo
